import type { ReactNode } from "react";
import type { StatusTone } from "@/lib/status-labels";
import styles from "./status-badge.module.css";

export function StatusBadge({ children, tone, className, size = "default" }: { children: ReactNode; tone?: StatusTone; className?: string; size?: "default" | "small" }) {
  return <span className={[styles.badge, tone && tone !== "default" ? styles[tone] : undefined, size === "small" ? styles.small : undefined, className].filter(Boolean).join(" ")}>{children}</span>;
}
